      field :subscribed_events, "subscribed_events", [:array, :string]
      field :created_at, "created_at", :datetime
      field :updated_at, "updated_at", :datetime
    end

    # One delivery attempt to a webhook destination. The first send of an event, each automatic retry and each resend
    # are separate deliveries.
    class WebhookDestinationDelivery < Didit::Model
      field :uuid, "uuid", :string
      field :session_id, "session_id", :string
      field :request_url, "request_url", :string
      field :response_status, "response_status", :integer
      field :response_time_ms, "response_time_ms", :integer
      field :status, "status", :string
      field :webhook_type, "webhook_type", :string
      field :created_at, "created_at", :datetime
    end

    # One delivery attempt to a webhook destination, with the exact request headers and body Didit sent.
    class WebhookDestinationDeliveryDetail < Didit::Model
      field :uuid, "uuid", :string
      field :session_id, "session_id", :string
      field :request_url, "request_url", :string
      field :response_status, "response_status", :integer
      field :response_time_ms, "response_time_ms", :integer
