      field :total_price, "total_price", :float
      field :min_price, "min_price", :float
      field :max_price, "max_price", :float
      field :features, "features", :string
      field :is_simple_workflow, "is_simple_workflow", :boolean
      field :is_editable, "is_editable", :boolean
